(() => {
  const needle = "mcpProbeAlpha";
  const describe = (el, level) => ({
    level, tag: el.tagName, id: el.id || null,
    classes: [...el.classList].slice(0, 8),
    role: el.getAttribute("role"), ariaLabel: el.getAttribute("aria-label"),
    data: Object.fromEntries([...el.attributes].filter(a => a.name.startsWith("data-"))
      .slice(0, 8).map(a => [a.name, String(a.value).slice(0, 60)])),
    text: (el.textContent || "").trim().slice(0, 60)
  });
  const chain = (el) => { const out = []; let node = el, level = 0;
    while (node && level < 4) { out.push(describe(node, level)); node = node.parentElement; level += 1; }
    return out; };
  const hits = [...document.querySelectorAll("*")]
    .filter(el => el.children.length === 0 && (el.textContent || "").includes(needle));
  const containers = new Set();
  hits.forEach(h => { const c = h.closest("table, [role=grid], [class*=variable], [class*=table]");
    containers.add(c || document.body); });
  const controls = new Set();
  containers.forEach(c => c.querySelectorAll("input, textarea, [contenteditable=true], button")
    .forEach(n => controls.add(n)));
  return {
    needle, hitCount: hits.length,
    hits: hits.slice(0, 4).map(el => ({ chain: chain(el),
      siblings: [...(el.parentElement?.children || [])].slice(0, 8).map(s => describe(s, 0)) })),
    controls: [...controls].slice(0, 12).map(n => describe(n, 0)),
    containerHtml: [...containers].slice(0, 1).map(c => (c.outerHTML || "").slice(0, 4000))
  };
})()
